const items = $input.all();
return items.map(item => {
  let ats = {};
  try {
    let r = item.json.output || '{}';
    if (typeof r === 'string') {
      r = r.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
      ats = JSON.parse(r);
    } else {
      ats = r;
    }
  } catch(e) {
    ats = { overallAtsScore: 0, recommendation: 'REJECT', resumeSummary: 'Parse error' };
  }

  const norm = $('Inject PDF Text into resumeText').item.json;

  // Phone: prefer ATS-extracted, fallback to what Inject node found
  let candidatePhone = String(ats.extractedPhone || norm.candidatePhone || '').trim();

  // Normalise to E.164
  if (candidatePhone) {
    let digits = candidatePhone.replace(/\D/g, '');
    if (digits.startsWith('0') && digits.length === 11) digits = '92' + digits.slice(1);
    candidatePhone = '+' + digits;
    if (digits.length < 7 || digits.length > 15) candidatePhone = '';
  }

  // Save to static data keyed by EMAIL (stable across both requests)
  if (candidatePhone && norm.candidateEmail) {
    const staticData = $getWorkflowStaticData('global');
    staticData['phone_' + norm.candidateEmail] = candidatePhone;
  }

  return {
    json: {
      ...ats,
      candidateName:  norm.candidateName,
      candidateEmail: norm.candidateEmail,
      candidatePhone,
      jobTitle:       norm.jobTitle,
      resumeText:     norm.resumeText,
      submittedAt:    norm.timestamp
    }
  };
});

