const body = $input.first().json.body || $input.first().json;
const msg = body.message || body;
const m = msg.call?.metadata || {};

// Extract Vapi structuredDataPlan output if present
const structured = msg.call?.analysis?.structuredData || {};
const transcript = structured.transcript || msg.transcript || [];

return [{ json: {
  transcript: Array.isArray(transcript) ? JSON.stringify(transcript) : String(transcript),
  callDurationSeconds: msg.durationSeconds || 0,
  callDurationMinutes: structured.callDurationMinutes || Math.round((msg.durationSeconds || 0) / 60),
  candidateName: structured.candidateName || m.candidateName || 'Unknown',
  candidateEmail: structured.candidateEmail || m.candidateEmail || '',
  candidatePhone: m.candidatePhone || '',
  jobTitle: structured.appliedPosition || m.jobTitle || 'General Position',
  resumeSummary: m.resumeSummary || '',
  sessionId: msg.call?.id || ('vapi_' + Date.now()),
  endedAt: new Date().toISOString(),
  conversationHistory: Array.isArray(transcript)
    ? transcript.map(t => t.role + ': ' + t.text).join('\n')
    : String(transcript),
  // Pass through Vapi's own scoring as context for evaluator
  vapiOverallScore: structured.overallScore || null,
  vapiRecommendation: structured.recommendationStatus || null,
  vapiStrengths: structured.strengths || [],
  vapiConcerns: structured.concerns || [],
  vapiKeyAnswers: structured.keyAnswers || {},
  vapiQuestionsAnswered: structured.questionsAnswered || null,
  interviewCompleted: structured.interviewCompleted ?? true
} }];

const item = $input.first();
const body = item.json.body ?? item.json;

const action              = body.action              ?? 'SCORE_RESUME';
const candidateName       = body.candidateName       ?? 'Unknown';
const candidateEmail      = body.candidateEmail      ?? '';
const jobTitle            = body.jobTitle            ?? 'General Position';
const message             = body.message             ?? '';
const sessionId           = body.sessionId           ?? ('session_' + Date.now());
const questionCount       = Number(body.questionCount ?? 0);
const conversationHistory = body.conversationHistory ?? '[]';
const resumeSummary       = body.resumeSummary       ?? '';
const timestamp           = new Date().toISOString();

// Resume text (only present on SCORE_RESUME)
let resumeText = body.resumeText ?? '';
if (!resumeText) {
  resumeText = item.json.text ?? item.json.data ?? '';
  if (Array.isArray(resumeText)) resumeText = resumeText.join('\n');
  else if (typeof resumeText === 'object' && resumeText !== null) resumeText = JSON.stringify(resumeText);
}
resumeText = String(resumeText).trim();

// Phone resolution
// Priority 1: static data keyed by EMAIL (set during SCORE_RESUME, survives across requests)
let candidatePhone = '';
if (candidateEmail) {
  const staticData = $getWorkflowStaticData('global');
  candidatePhone = staticData['phone_' + candidateEmail] || '';
}

// Priority 2: explicitly in webhook body
if (!candidatePhone) {
  candidatePhone = String(body.candidatePhone ?? '').trim();
}

// Priority 3: extract from PDF text (only works on SCORE_RESUME)
if (!candidatePhone && resumeText) {
  const phoneRegex = /(?:\+?\d[\s\-.]?)?(?:\(?\d{2,4}\)?[\s\-.]?){2,}\d{3,}/g;
  const rawMatches = resumeText.match(phoneRegex) || [];
  const validMatch = rawMatches.find(m => m.replace(/\D/g, '').length >= 7);
  if (validMatch) candidatePhone = validMatch.replace(/[\s\-]/g, '');
}

// E.164 normalisation
if (candidatePhone) {
  let digits = candidatePhone.replace(/\D/g, '');
  if (digits.startsWith('0') && digits.length === 11) digits = '92' + digits.slice(1);
  candidatePhone = '+' + digits;
  if (digits.length < 7 || digits.length > 15) candidatePhone = '';
}

const hasBinaryResume = resumeText.length > 10;

return [{
  json: {
    action,
    candidateName,
    candidateEmail,
    candidatePhone,
    jobTitle,
    resumeText,
    message,
    sessionId,
    questionCount,
    conversationHistory,
    resumeSummary,
    timestamp,
    hasBinaryResume
  }
}];
